import{z as h,x as B,o as e,c as d,q as s,j as o,D as t,d as E,s as i,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"GRU 对照","description":"","frontmatter":{"title":"GRU 对照","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/gru-vs-lstm.md","filePath":"llm/gru-vs-lstm.md","lastUpdated":1791413859000}'),p={name:"llm/gru-vs-lstm.md"};function A(_,a,m,u,c,T){const l=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=s('<h1 id="gru-对照" tabindex="-1">GRU 对照 <a class="header-anchor" href="#gru-对照" aria-label="Permalink to &quot;GRU 对照&quot;">​</a></h1><div class="epigraph"><p>不必维持单独的细胞与隐状态两套向量；重置门与更新门也能做出可加的记忆，只是接口更瘦。</p><footer>—— 据 Cho et al., Learning Phrase Representations using RNN Encoder–Decoder, EMNLP 2014 整理</footer></div><p><a href="/llm/lstm-gating">LSTM 门控</a>给出 \\(c_t\\) 与三个门。本课不重写常数误差转盘。缺口是：许多任务上并不需要输出门把细胞再包一层 \\(\\tanh\\)；参数与状态可以更少。GRU 把记忆放在 \\(h_t\\) 自己里，用更新门做插值、重置门控制候选如何读旧状态。本课对照机制，不宣布谁永远更好，也不进入编码器—解码器的整体图——那是下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LSTM 每步要维护 \\(c\\) 与 \\(h\\)，四组仿射。部署与小数据上，这是明显的常数倍。问题：加法记忆是否必须拆成「细胞 + 读出门」？GRU 的回答是：用 \\(z_t\\) 在旧 \\(h\\) 与新候选之间插值，</p> \\[h_t=(1-z_t)\\odot h_{t-1}+z_t\\odot\\tilde h_t, \\]<p>这已经是残差式加法。重置门 \\(r_t\\) 乘在计算 \\(\\tilde h_t\\) 时所读的 \\(h_{t-1}\\) 上，让候选可以忽略过去。缺口是同一长程动机下的另一参数化，便于后课 seq2seq 论文（Cho 等人正是在编码器—解码器里提出 GRU）时能读懂符号。</p><p>没有单独的输出门，意味着 \\(h_t\\) 既是记忆也是对外接口。不能再「细胞里记着、对外少露」。这是表达力与简洁的权衡，不是实现省略。</p><p><span class="marginnote">术语翻译：更新门 \\(z_t\\) 是新旧记忆之间的「调音台推子」——\\(z\\) 接近 0 就照抄旧记忆，接近 1 就整个换成新候选；重置门 \\(r_t\\) 则是写候选时「要不要参考过去」的开关：关掉它，候选只看当前输入，像局部改写而不动旧账。</span></p><h3 id="gru-不是-lstm-去掉一个门这么算术" tabindex="-1">GRU 不是 LSTM 去掉一个门这么算术 <a class="header-anchor" href="#gru-不是-lstm-去掉一个门这么算术" aria-label="Permalink to &quot;GRU 不是 LSTM 去掉一个门这么算术&quot;">​</a></h3><p>LSTM 的遗忘与输入在通行实现里往往耦合（\\(i=1-f\\) 的变体），看起来也像插值，但细胞仍经 \\(\\tanh\\) 与输出门才成为 \\(h\\)。GRU 的插值直接发生在 \\(h\\) 空间，候选的非线性与重置纠缠。把参数量除以 \\(3/4\\) 当成两者的定义差，会漏掉状态是否分开这条几何。对照时应说「记忆是否另存、\\(h\\) 是否直接被加」，而不是只数 sigmoid 个数。</p><p><span class="marginnote">Cho et al., EMNLP 2014 的符号与后来教材略有出入。本课用更新门 \\(z\\)、重置门 \\(r\\) 的通行写法。读原文时以论文公式为准，不要混用 LSTM 的 \\(f,i,o\\) 名字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从 \\((h_{t-1},x_t)\\) 算 \\(z_t,r_t\\)，候选 \\(\\tilde h_t=\\tanh(W x_t+U(r_t\\odot h_{t-1}))\\)，再按 \\(z_t\\) 插值得到 \\(h_t\\)。反向沿插值的 \\((1-z)\\) 支路可以把梯度送到很早的 \\(h\\)，与 LSTM 的 \\(f\\approx 1\\) 同类。初始化更新门偏向「保持」同样有用。与 LSTM 一样，沿时间串行。解码器里用 GRU 还是 LSTM 不改变下一课的定长交接。</p>',14)),(e(),o(n,null,{default:t(()=>[i(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20HPREV%5B%22h%20%E4%B8%8A%E4%B8%80%E6%97%B6%E5%88%BB%22%5D%20--%3E%20Z%5B%22%E6%9B%B4%E6%96%B0%E9%97%A8%E6%8F%92%E5%80%BC%22%5D%0A%20%20HPREV%20--%3E%20R%5B%22%E9%87%8D%E7%BD%AE%E5%90%8E%E7%AE%97%E5%80%99%E9%80%89%22%5D%0A%20%20R%20--%3E%20CAND%5B%22%E5%80%99%E9%80%89%20h%20%E6%B3%A2%E6%B5%AA%22%5D%0A%20%20CAND%20--%3E%20Z%0A%20%20Z%20--%3E%20HNOW%5B%22%E6%96%B0%E7%9A%84%20h%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"长程：更新门接近 \\(0\\) 的维（按上式 \\((1-z)\\approx 1\\)）把 \\(h\\) 原样传递。短程改写走候选。重置门关闭时，候选几乎不看过去，相当于局部重写而不污染记忆维。经验上 GRU 与 LSTM 在许多基准上接近，差别小于学习率与层数；本课不提供排行。选择往往来自实现与延迟：少一组仿射，少一份状态。",-1)),(e(),o(n,null,{default:t(()=>[i(l,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22LSTM%22%5D%20--%3E%20L1%5B%22%E4%B8%89%E9%81%93%E9%97%A8%EF%BC%9A%E9%81%97%E5%BF%98%20f%20%2F%20%E8%BE%93%E5%85%A5%20i%20%2F%20%E8%BE%93%E5%87%BA%20o%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E7%BB%86%E8%83%9E%20c%20%E4%B8%8E%E9%9A%90%E7%8A%B6%E6%80%81%20h%20%E5%88%86%E5%BC%80%E5%AD%98%22%5D%0A%20%20L2%20--%3E%20L3%5B%22h%20%E8%A6%81%E7%BB%8F%20tanh%20%E4%B8%8E%E8%BE%93%E5%87%BA%E9%97%A8%E6%89%8D%E9%9C%B2%E5%87%BA%22%5D%0A%20%20G%5B%22GRU%22%5D%20--%3E%20G1%5B%22%E4%B8%A4%E9%81%93%E9%97%A8%EF%BC%9A%E6%9B%B4%E6%96%B0%20z%20%2F%20%E9%87%8D%E7%BD%AE%20r%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E5%8F%AA%E6%9C%89%E4%B8%80%E5%A5%97%E7%8A%B6%E6%80%81%20h%EF%BC%8C%E7%9B%B4%E6%8E%A5%E6%8F%92%E5%80%BC%22%5D%0A%20%20G2%20--%3E%20G3%5B%22%E8%AE%B0%E5%BF%86%E4%B8%8E%E5%AF%B9%E5%A4%96%E6%8E%A5%E5%8F%A3%E6%98%AF%E5%90%8C%E4%B8%80%E4%B8%AA%E5%90%91%E9%87%8F%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p>堆叠多层 GRU 时，层与层之间仍建议走残差或至少对齐宽度，否则时间轴刚修好的增益会在深度轴上再乘一遍 \\(\\rho\\)。这与前馈课相同：门控解决的是沿 \\(t\\) 的乘法，不是沿层的乘法。双向 GRU 只是两个方向各一条递推，拼接后仍是定长交接的候选，并不提供对任意 \\(j\\) 的读取。</p><p><span class="marginnote">数字实例：隐状态 512 维、输入也是 512 维时，LSTM 每个单元约有 \\(4 \\times 1024 \\times 512 \\approx 210\\) 万参数，GRU 三组仿射约 157 万，直接省四分之一——这就是「少一份状态、少一道门」换来的部署便宜。</span></p><p>两者都没有解决「回头看某一个过去位置」：要读 \\(x_3\\)，必须它当时被写入并一路传到现在。编码器把整句压进一个 \\(h_n\\) 时，这个瓶颈下一课会变得刺眼。</p><p><span class="marginnote">常见误区：把 GRU 当成「LSTM 的低成本劣化版」。多数基准上两者差距小于调学习率、加层数带来的影响；选型常取决于实现便利与延迟，而不是表达能力上一锤定音。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写注意力。下一课<a href="/llm/seq2seq-encode-decode">Seq2Seq 编码解码</a>把 GRU/LSTM 装进「一句进、一句出」的两个循环。后课默认：门控 RNN 作为可训的长程递推，LSTM 与 GRU 可互换地当作编码器积木，差别写在状态是否分家。不在本课根据某一基准宣布胜负。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GRU 用更新门在旧隐状态与候选之间插值，加法记忆不必另设细胞。</li><li>重置门控制候选是否阅读过去；没有 LSTM 那样的输出门。</li><li>对照看几何，不要只数门的个数。</li><li>仍是串行递推，不能随机访问过去某步。</li><li>多层时深度轴上的增益要另管，门控只修时间轴。</li><li>出处：Cho et al., EMNLP 2014。</li></ul>',8))])}const R=h(p,[["render",A]]);export{L as __pageData,R as default};
